mapper.select:
SELECT 1
  FROM users
  WHERE legacy_identifier = #{legacyIdentifier}
    AND tenants_id = #{tenantId}

    AND id != #{userId}

  LIMIT 1


WHERE COALESCE(u.breached_password_status, i.breached_password_status) IS NOT NULL
AND COALESCE(u.breached_password_status, i.breached_password_status) != 0 

  AND u.tenants_id = #{tenantId}

LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(DISTINCT(u.id)) FROM users u LEFT JOIN identities AS i ON u.id = i.users_id
WHERE COALESCE(u.breached_password_status, i.breached_password_status) IS NOT NULL AND COALESCE(u.breached_password_status, i.breached_password_status) != 0
AND u.tenants_id = #{tenantId}

WHERE u.id = ( SELECT users_id FROM
(
SELECT users_id, 1 as type FROM identities ii WHERE ii.value = UPPER(#{loginId}) AND ii.type = 1 AND ii.tenants_id = #{tenantId}
UNION ALL
SELECT users_id, 1 as type FROM identities ii WHERE ii.username_index = UPPER(#{loginId}) AND ii.tenants_id = #{tenantId}
SELECT users_id, 0 as type FROM identities ii WHERE ii.value = #{loginId} AND ii.type = 0 AND ii.tenants_id = #{tenantId}
UNION ALL
SELECT users_id, 0 as type FROM identities ii WHERE ii.email = #{loginId} AND ii.tenants_id = #{tenantId}
SELECT users_id, ii.type FROM identities ii WHERE ii.value = #{loginId} AND ii.type = #{loginIdType} AND ii.tenants_id = #{tenantId}
) AS t1
ORDER BY array_position(#{idType}, t1.type::smallint)
ORDER BY FIELD(t1.type, #{idType})
LIMIT 1 )


WHERE u.id IN (
#{id}
)

  AND u.tenants_id = #{tenantId}

SELECT count(id)
  FROM users
  WHERE tenants_id = #{tenantId}


WHERE u.id = (
  SELECT users_id FROM
    (


        SELECT users_id FROM identities ii
        WHERE

          ii.users_id != #{userId} AND

        ii.email = #{loginId}
        AND ii.tenants_id = #{tenantId}

        UNION ALL

        SELECT users_id FROM identities ii
        WHERE

          ii.users_id != #{userId} AND

        type = #{identityType} AND ii.value = #{loginId}
        AND ii.tenants_id = #{tenantId}


        SELECT users_id FROM identities ii
        WHERE

          ii.users_id != #{userId} AND

        ii.username_index = UPPER(#{loginId})
        AND ii.tenants_id = #{tenantId}

        UNION ALL

        SELECT users_id FROM identities ii
        WHERE

          ii.users_id != #{userId} AND

        type = #{identityType} AND ii.value = UPPER(#{loginId})
        AND ii.tenants_id = #{tenantId}


        SELECT users_id FROM identities ii
        WHERE

          ii.users_id != #{userId} AND

        type = #{identityType} AND ii.value = #{loginId}
        AND ii.tenants_id = #{tenantId}


    ) as t1
  LIMIT 1
)


WHERE ur.users_id
IN  (

    #{userId}

  )


WHERE u.parent_email IS NOT NULL
AND u.insert_instant < #{cutoff}

  AND u.tenants_id = #{tenantId}

ORDER by u.insert_instant DESC
-- This is currently only used for reaping, and it will be called on a schedule. Limit how much damage we do in one go.
LIMIT 500

WHERE i.verified IS FALSE -- only reason 4 (pending) is a truly unverified identity in 1.59.0 and later -- legacy FusionAuth (versions earlier than 1.59.0) will have a null value in this column. AND (i.verified_reason = 4 OR i.verified_reason IS NULL) AND u.insert_instant > #{start} AND u.insert_instant < #{cutoff} AND u.verified_instant IS NULL -- legacy users will not have u.verified_instant populated yet. we can identify them because their identities row does not have a type -- if they do not have a type and i.verified_instant is NULL, they have never been verified. AND (i.type IS NOT NULL OR i.verified_instant IS NULL)
AND u.tenants_id = #{tenantId}
ORDER by u.insert_instant DESC -- This is currently only used for reaping, and it will be called on a schedule. Limit how much damage we do in one go. LIMIT 500


WHERE ur.applications_id = #{applicationId}
AND ur.insert_instant > #{start}
AND ur.insert_instant < #{cutoff}
AND ur.verified IS FALSE
-- This should never be non-null since you cannot un-verify a registration. But we still expect this to be null when eligible for reaping.
AND ur.verified_instant IS NULL
ORDER by ur.insert_instant DESC
-- This is currently only used for reaping, and it will be called on a schedule. Limit how much damage we do in one go.
LIMIT 500

mapper.sql:
FROM users AS u -- get all the identities for the user that match one of the identities table WHERE clauses below LEFT OUTER JOIN identities AS i_match ON u.id = i_match.users_id ${additionalJoins} WHERE ( lower(u.first_name) LIKE #{searchTerm} OR lower(u.last_name) LIKE #{searchTerm} OR lower(u.full_name) LIKE #{searchTerm} OR lower(i_match.email) LIKE #{searchTerm} OR lower(i_match.username) LIKE #{searchTerm} OR lower(i_match.value) LIKE #{searchTerm} OR -- Remove all non-numeric characters from the phone number and, if there is still anything left besides the wildcard %% characters, -- complete the search with the numeric values
(i_match.value IS NOT NULL AND i_match.type = 2 AND REGEXP_REPLACE(#{searchTerm}, '[^0-9%]', '', 'g') != '%%' AND REGEXP_REPLACE(i_match.value, '[^0-9]', '', 'g') LIKE REGEXP_REPLACE(#{searchTerm}, '[^0-9%]', '', 'g'))
(i_match.value IS NOT NULL AND i_match.type = 2 AND REGEXP_REPLACE(#{searchTerm}, '[^0-9%]', '') != '%%' AND REGEXP_REPLACE(i_match.value, '[^0-9]', '') LIKE REGEXP_REPLACE(#{searchTerm}, '[^0-9%]', ''))
)
AND u.tenants_id = #{tenantId}

mapper.select:
SELECT id, ${orderByAggregate} FROM ( SELECT u.id as id,
CASE WHEN i_sort.type = 0 THEN i_sort.value WHEN i_sort.type IS NULL THEN i_sort.email END AS email, CASE WHEN i_sort.type = 2 THEN i_sort.value END AS phone_number, CASE WHEN i_sort.type = 1 THEN i_sort.value WHEN i_sort.type is NULL THEN i_sort.username_index END AS username, LOWER(
COALESCE(CASE WHEN i_sort.type = 0 THEN i_sort.value WHEN i_sort.type IS NULL THEN i_sort.email END, CASE WHEN i_sort.type = 1 THEN i_sort.value WHEN i_sort.type is NULL THEN i_sort.username_index END, CASE WHEN i_sort.type = 2 THEN i_sort.value END ) ) AS login, u.birth_date, u.full_name, u.insert_instant, u.last_login_instant, u.tenants_id
) subquery
GROUP BY id, tenants_id
ORDER BY ${orderByOuter} LIMIT #{limit} OFFSET #{offset};

mapper.update:
UPDATE user_registrations
SET
username_status = #{contentStatus}
WHERE clean_speak_id IN (

  #{cleanSpeakId}

)

UPDATE identities i
INNER JOIN users u ON i.users_id = u.id
SET
username_status = #{contentStatus}
WHERE u.clean_speak_id IN (

  #{cleanSpeakId}

)

UPDATE identities i
SET
username_status = #{contentStatus}
FROM users u
WHERE i.users_id = u.id
AND
u.clean_speak_id IN (

  #{cleanSpeakId}

)

UPDATE users
SET data = JSON_SET(CAST(data AS JSON),
'$.twoFactor.recoveryCodes', JSON_ARRAY(

  #{recoveryCode}

),
'$.twoFactor.recoveryCodeEncryptionScheme', IFNULL(#{user.twoFactor.recoveryCodeEncryptionScheme}, CAST('null' AS JSON)),
'$.twoFactor.recoveryCodeWorkFactor', IFNULL(#{user.twoFactor.recoveryCodeWorkFactor}, CAST('null' AS JSON))
)
WHERE id = #{user.id}

UPDATE users SET data = JSONB_SET(JSONB_SET(JSONB_SET(data::JSONB, '{twoFactor, recoveryCodes}', JSONB_BUILD_ARRAY(
#{recoveryCode}::TEXT
)), '{twoFactor, recoveryCodeEncryptionScheme}', COALESCE(TO_JSONB(#{user.twoFactor.recoveryCodeEncryptionScheme}::TEXT), 'null'::jsonb)), '{twoFactor, recoveryCodeWorkFactor}', COALESCE(TO_JSONB(#{user.twoFactor.recoveryCodeWorkFactor}::INTEGER), 'null'::jsonb)) WHERE id = #{user.id}

UPDATE users
SET verified_instant = #{verifiedInstant}
  WHERE id = #{userId}

UPDATE users
SET parent_email = NULL
  WHERE id = #{id}
